package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed application of CandidateFactory's wait-only duration correction. */
final class BuyReplacementCalibratedDurationEvaluator {
 BuyReplacementCalibratedDurationEvaluationSet evaluate(BuyReplacementDurationCalibrationInputContext s,long at){if(s==null||at<s.getComposedAt()||s.getComposedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||!Double.isFinite(s.getWaitMultiplier())||s.getWaitMultiplier()<0)return null;List<BuyReplacementCalibratedDurationEvaluation> out=new ArrayList<>(s.getEvaluations().size());for(BuyReplacementRoundTripCompletionEvaluation e:s.getEvaluations()){if(!valid(e,s))return null;double b=correct(e.getBuyExpectedHours(),e.getBuyWaitHours(),s.getWaitMultiplier());double x=correct(e.getSellExpectedHours(),e.getSellWaitHours(),s.getWaitMultiplier());if(!Double.isFinite(b)||b<0||!Double.isFinite(x)||x<0)return null;out.add(new BuyReplacementCalibratedDurationEvaluation(e,b,x));}return new BuyReplacementCalibratedDurationEvaluationSet(s,out,at);}
 private static double correct(double expected,double wait,double multiplier){if(wait<=0||Double.isNaN(wait)||Double.isInfinite(wait))return expected;double working=Math.max(0,expected-wait);return wait*multiplier+working;}
 private static boolean valid(BuyReplacementRoundTripCompletionEvaluation e,BuyReplacementDurationCalibrationInputContext s){return e!=null&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&Double.isFinite(e.getBuyExpectedHours())&&e.getBuyExpectedHours()>=0&&!Double.isNaN(e.getBuyWaitHours())&&e.getBuyWaitHours()>=0&&Double.isFinite(e.getSellExpectedHours())&&e.getSellExpectedHours()>=0&&!Double.isNaN(e.getSellWaitHours())&&e.getSellWaitHours()>=0&&Double.compare(e.getCompletionProbability(),e.getBuyProbability()*e.getSellProbability())==0;}
}
